def syllabus_to_modules(apps, schema_editor):
    """Convert the old one-text-box syllabus ('# Module' lines + topic lines) into Module/Topic rows."""
    Course, Module, Topic = (apps.get_model('courses', n) for n in ('Course', 'Module', 'Topic'))
    for course in Course.objects.all():
        module, mo, to = None, 0, 0
        for line in (course.syllabus or '').splitlines():
            line = line.strip()
            if not line:
                continue
            if line.startswith('#'):
                module = Module.objects.create(course=course, title=line.lstrip('# ').strip() or 'Topics', order=mo)
                mo, to = mo + 1, 0
            else:
                if module is None:
                    module = Module.objects.create(course=course, title='Topics', order=mo)
                    mo, to = mo + 1, 0
                Topic.objects.create(module=module, title=line[:200], order=to)
                to += 1


